16	/**
17	 * 幂等执行器：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果快照，
18	 * 同键异参返回 409 且不改变作业状态。幂等记录与业务写入同事务提交。
19	 */
20	@Service
21	public class IdempotencyService {
22	
23	    private final IdempotencyRepository repository;
24	    private final ObjectMapper objectMapper;
25	    private final TransactionTemplate transactionTemplate;
26	
27	    public IdempotencyService(IdempotencyRepository repository, ObjectMapper objectMapper,
28	                              TransactionTemplate transactionTemplate) {
29	        this.repository = repository;
30	        this.objectMapper = objectMapper;
31	        this.transactionTemplate = transactionTemplate;
32	    }
33	
34	    /**
35	     * 幂等执行操作。
36	     *
37	     * @param requestId    幂等请求键
38	     * @param operation    操作类型
39	     * @param request      业务请求（指纹覆盖其全部字段）
40	     * @param responseType 响应类型
41	     * @param action       业务动作
42	     * @return 首次执行结果或重放的首次结果快照
43	     */
44	    public <T> T execute(String requestId, String operation, Object request,
45	                         Class<T> responseType, Supplier<T> action) {
46	        String fingerprint = fingerprint(operation, requestId, request);
47	        var existing = repository.findByRequestId(requestId);
48	        if (existing.isPresent()) {
49	            return replay(existing.get(), operation, fingerprint, responseType);
50	        }
51	        try {
52	            return transactionTemplate.execute(status -> {
53	                repository.insert(requestId, operation, fingerprint, "{}");
54	                T result = action.get();
55	                repository.updateResponseBody(requestId, writeJson(result));
56	                return result;
57	            });
58	        } catch (DuplicateKeyException e) {
59	            var row = repository.findByRequestId(requestId);
60	            if (row.isEmpty()) {
61	                throw e;
62	            }
63	            return replay(row.get(), operation, fingerprint, responseType);
64	        }
65	    }
66	
67	    private <T> T replay(IdempotencyRow row, String operation, String fingerprint, Class<T> responseType) {
68	        if (!row.operation().equals(operation) || !row.fingerprint().equals(fingerprint)) {
69	            throw new ConflictException("幂等键冲突：同键异参，不改变作业状态");
70	        }
71	        try {
72	            return objectMapper.readValue(row.responseBody(), responseType);
73	        } catch (Exception e) {
74	            throw new IllegalStateException("幂等快照反序列化失败", e);
75	        }
76	    }
77	
78	    private String fingerprint(String operation, String requestId, Object request) {
79	        try {
80	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
81	            String material = operation + '\n' + requestId + '\n' + writeJson(request);
82	            return HexFormat.of().formatHex(digest.digest(material.getBytes(StandardCharsets.UTF_8)));
83	        } catch (NoSuchAlgorithmException e) {
84	            throw new IllegalStateException("SHA-256 不可用", e);
85	        }
86	    }
87	
88	    private String writeJson(Object value) {
89	        try {
90	            return objectMapper.writeValueAsString(value);
91	        } catch (Exception e) {
92	            throw new IllegalStateException("请求序列化失败", e);
93	        }
94	    }
