        assertThrows(ConflictException.class, () -> resume("c1-re1", job.id(), d.id(), 4));
        // 待批准途中试验与确认已失效
        EnRouteDispositionEvidence evidence = enRouteService.getDispositionEvidence(job.id(), d.id());
